#include "app.h"
#include "video_sw.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
/* Preprocessed native GX RGBA8 tiles. No PNG decoding, no network calls or
 * large allocations on every rendered frame. Generated by cover_sync.py. */
#define COV_W 128
#define COV_H 176
#define COV_BYTES (COV_W*COV_H*4)
typedef struct { char key[120]; void *pixels; int valid; int system; unsigned last; unsigned height,tint; } Cache;
static Cache cache[12];static unsigned clock_id=0;
static void key_for(const Game*g,char*key,size_t cap){
 if(g->id[0]){snprintf(key,cap,"%s",g->id);return;}
 size_t n=0;for(const char*p=g->name;*p&&n+1<cap;p++){
  unsigned char c=(unsigned char)*p;if(c>='a'&&c<='z')c-=32;
  if((c>='A'&&c<='Z')||(c>='0'&&c<='9'))key[n++]=c;
  else if(c==' '&&n&&key[n-1]!='-')key[n++]='-';
 }key[n]=0;
}
/* Disk I/O is strictly forbidden from the render path. The first
 * request for a new cover is handled in cover_prefetch between frames.
 * A negative cache entry avoids repeatedly opening missing files. */
static Cache*lookup(const Game*g,int allow_io){
 if(!g||g->system<0||g->system>=SYSTEM_COUNT)return NULL;
 char key[120];key_for(g,key,sizeof(key));if(!*key)return NULL;
 clock_id++;
 for(int j=0;j<12;j++)if(cache[j].key[0]&&cache[j].system==(int)g->system&&!strcmp(cache[j].key,key)){
  cache[j].last=clock_id;return cache[j].valid?&cache[j]:NULL;
 }
 if(!allow_io)return NULL;
 int slot=-1;for(int j=0;j<12;j++)if(!cache[j].key[0]){slot=j;break;}
 if(slot<0){slot=0;for(int j=1;j<12;j++)if(cache[j].last<cache[slot].last)slot=j;}
 Cache*c=&cache[slot];
 /* CPU rendering completes before this cache entry is recycled. */
 free(c->pixels);
 memset(c,0,sizeof(*c));
 snprintf(c->key,sizeof(c->key),"%s",key);c->system=(int)g->system;c->last=clock_id;
 static const char*folders[SYSTEM_COUNT]={
  "wii","gc","ps1","snes","nes","gba","gb","media"
 };
 char p[220];FILE*f=NULL;
 /* Prefer the same device as the ROM, then the alternate storage.
  * Scoped artwork avoids collisions between equally named systems.
  * Legacy flat folders are still accepted for existing users. */
 const char *first=!strncmp(g->path,"sd:/",4)?"sd":"usb";
 const char *other=!strcmp(first,"sd")?"usb":"sd";
 const char *devices[2]={first,other};
 for(int root=0;root<2&&!f;root++){
  const char *device=devices[root];
  for(int scoped=1;scoped>=0&&!f;scoped--){
   if(scoped)snprintf(p,sizeof(p),"%s:/maizo/covers/%s/%s.gxt",device,folders[g->system],key);
   else snprintf(p,sizeof(p),"%s:/maizo/covers/%s.gxt",device,key);
   f=fopen(p,"rb");
  }
 }
 if(!f)return NULL;
 unsigned char hdr[8];
 if(fread(hdr,1,8,f)!=8||memcmp(hdr,"MZG1",4)||hdr[4]!=0||hdr[5]!=COV_W||hdr[6]!=0||(hdr[7]!=160&&hdr[7]!=176)){fclose(f);return NULL;}
 c->height=hdr[7];
 size_t bytes=(size_t)COV_W*c->height*4u;
 c->pixels=malloc(bytes);if(!c->pixels){fclose(f);return NULL;}
 if(fread(c->pixels,1,bytes,f)!=bytes){free(c->pixels);c->pixels=NULL;fclose(f);return NULL;}
 fclose(f);
 /* Compute a muted ambient palette once, never on the hot drawing path. */
 unsigned rs=0,gs=0,bs=0,samples=0;
 const unsigned char *pixel=(const unsigned char *)c->pixels;
 for(unsigned yy=16;yy+12<c->height;yy+=16){
  for(unsigned xx=16;xx<112;xx+=16){
   unsigned base=((yy/4)*32+xx/4)*64+(((yy&3)*4+(xx&3))*2);
   unsigned r=pixel[base+1],g=pixel[base+32],b=pixel[base+33];
   if(r+g+b<80)continue;
   rs+=r;gs+=g;bs+=b;samples++;
  }
 }
 if(samples){
  unsigned r=12+rs/samples/5,g=12+gs/samples/5,b=12+bs/samples/5;
  c->tint=0xff000000u|(r<<16)|(g<<8)|b;
 }
 c->valid=1;return c;
}
/* The UI can always render a placeholder without blocking on FAT. */
int cover_draw(const Game*g,float x,float y,float w,float h){
 Cache*c=lookup(g,0);
 if(!c)return 0;
 /* Letterbox older 128x160 covers instead of stretching into the new
  * portrait card frame. Preserve even square source images via preprocessing. */
 float wanted=(float)COV_W/(float)c->height;
 float box=w/h;
 if(box<wanted){float newh=w/wanted;y+=(h-newh)*0.5f;h=newh;}
 else {float neww=h*wanted;x+=(w-neww)*0.5f;w=neww;}
 maizo_video_cover((const unsigned char*)c->pixels,COV_W,c->height,x,y,w,h);
 return 1;
}

/* RAM-only color lookup: never stall the interface to read a drive. */
unsigned cover_tint(const Game*g){
 if(!g)return 0;
 char key[120];key_for(g,key,sizeof(key));
 for(unsigned i=0;i<sizeof(cache)/sizeof(cache[0]);i++)
  if(cache[i].valid && cache[i].system==(int)g->system &&
     strcmp(cache[i].key,key)==0)return cache[i].tint;
 return 0;
}

/* The main loop runs at most one new file request per video frame.
 * Safe to call repeatedly; after first success or failure it is RAM-only. */
void cover_prefetch(const Game*g){
 (void)lookup(g,1);
}
/* Explicit rescan/changed media: forget old negative entries and textures.
 * Never touch running WiiMC/Nintendont modules: this is frontend-only. */
void cover_reset(void){
 for(unsigned i=0;i<sizeof(cache)/sizeof(cache[0]);i++){
  free(cache[i].pixels);
  memset(&cache[i],0,sizeof(cache[i]));
 }
 clock_id=0;
}
